protocol ExprSym {
    associatedtype Repr
    func lit(_ i: Int) -> Repr
    func add(_ l: Repr, _ r: Repr) -> Repr
}

func exp<S: ExprSym>(_ s: S) -> S.Repr { s.add(s.lit(1), s.add(s.lit(2), s.lit(4))) }

struct Eval: ExprSym {
    func lit(_ i: Int) -> Int { i }
    func add(_ l: Int, _ r: Int) -> Int { l + r }
}
